type TranslationPart = Readonly<{
  entry: string
  source?: string
}>

type TranslationParts = Readonly<{
  manifest: string
  lift?: TranslationPart
  embed?: TranslationPart
  render?: TranslationPart
  transduce?: TranslationPart
}>

const TRANSLATION: TranslationParts = Object.freeze({
  manifest: `{
  "$schema": "https://tabnas.dev/schema/plugin.schema.json",
  "name": "@tabnas/yaml",
  "go": "github.com/tabnas/yaml/go",
  "rust": "tabnas-yaml",
  "description": "YAML parsing for the tabnas engine.",
  "base": "@tabnas/jsonic",
  "engine": "@tabnas/parser",
  "grammar": "yaml-grammar.jsonic",
  "extensions": [
    ".yaml",
    ".yml"
  ],
  "mediaTypes": [
    "application/yaml"
  ],
  "languageId": "yaml",
  "pluginKind": "grammar",
  "grammarKind": "closure",
  "lexStream": "clean",
  "syncGroups": [
    "end",
    "comma",
    "close",
    "sync"
  ],
  "specDir": "test/spec",
  "clib": {
    "dir": "go/clib",
    "library": "libtabnasyaml",
    "abi": "v1",
    "errorCodes": [
      "usage",
      "grammar",
      "handle",
      "internal"
    ]
  },
  "errorCodes": [],
  "docs": "https://tabnas.dev/docs/packages",
  "repository": "https://github.com/tabnas/yaml",
  "versionSource": "ts/package.json",
  "translate": {
    "reads": "tree",
    "writes": "tree",
    "root": "any",
    "render": "alchemy/render.alc",
    "transduce": "alchemy/transduce.alc",
    "loss": [
      "Comments are not kept.",
      "Anchors and aliases are not kept: an alias is written as a copy of the value it names.",
      "Tags are not kept.",
      "Styles are not kept: every string and key is written double-quoted, and every collection in block style.",
      "A stream of several documents is written as one document, a sequence of them."
    ]
  }
}
`,
  render: Object.freeze({ entry: "yaml-render", source: `; YAML's render: a tree's events written as one YAML 1.2 document in
; block style. This is a library of definitions, each named \`yaml-...\`,
; which a host links with its own program (alchemy's \`compile_sources\`);
; its entry point is \`yaml-render\`, and nothing else here is the host's to
; call.
;
; The profile is always-quoted, as the CSV renderer's is: every string
; and every key is double-quoted (\`quoted\`: JSON's escapes, which YAML's
; double-quoted style reads, and the C1 controls and the noncharacters
; U+FFFE and U+FFFF, which its printable set excludes; and the line
; separators U+2028 and U+2029 escaped as well, which YAML 1.2 reads as
; themselves and YAML 1.1 as line breaks), so that no string reads back
; as a boolean, a null, a number, a nested mapping or the merge key
; \`<<\`. A number is its lexeme, or as the JSON renderer writes it when
; it has none, and a non-finite one is \`.inf\`, \`-.inf\` or \`.nan\`,
; whatever its lexeme. A mapping under a key, and a sequence under a key
; or inside a sequence, start on the next line, two spaces in; a
; sequence item is \`- \`, and a mapping in a sequence has its first key
; on the item's line. A container's opening is held until its first
; child or its end, so an empty one is \`{}\` or \`[]\` on its key's line. A
; key whose written form is longer than 1024 characters, past which YAML
; stops reading an implicit key, is written explicitly, \`? key\` on its
; own line.
;
; The events are a tree's: a mapping holds each key once. A walked value
; is one by construction; a host that streams a parse must refuse a
; member the parse repeats, since the render writes what it is given and
; YAML forbids a repeated key.
;
; The state is the stack of open containers, one marker each, so it grows
; with a document's nesting and never with its width: \`:object-open\` and
; \`:array-open\` for a container with nothing written yet, \`:object\` for a
; mapping waiting for a key, \`:member\` for one whose key is written and
; waits for the value, and \`:array\` for a sequence waiting for an item.
; Once the root value is written the state is \`[:root-done]\`, and nothing
; may follow it. Events no tree has fail with PROTOCOL_ORDER_ERROR,
; saying so.
;
; Each value directly inside the root mapping or sequence is a record of
; the text: the step that ends one answers alchemy's \`:record-end\` after
; its outputs, and so does the step that opens the root, so a host's
; writer holds a record until its end, and a run that fails part way
; leaves whole records behind.

def yaml-indent [s]
  repeat (count s) "  "

; The top marker, or \`:none\` before the root value.
def yaml-top [s]
  match (count s)
    case 0 :none
    case _ (top s)

; The top container under another marker.
def yaml-mark [marker s]
  push marker (pop s)

; A value completed: a mapping waiting for its member's value waits for
; its next key, and the root value, once written, is the document.
def yaml-done [s]
  match (count s)
    case 0 [:root-done]
    case _
      match (yaml-top s)
        case :member (yaml-mark :object s)
        case _ s

; What comes before a value whose parent is the top of s: a space on the
; key's line, or a dash, for a scalar or an empty container; a line break
; and the indentation for a mapping under a key; a line break for a
; sequence under a key; a dash and the first key for a mapping in a
; sequence; a dash alone for a sequence in a sequence.
def yaml-lead [shape s]
  match (count s)
    case 0 ""
    case _
      match (yaml-top s)
        case :member
          match shape
            case :mapping (concat "\\n" (yaml-indent s))
            case :sequence "\\n"
            case _ " "
        case :array
          match shape
            case :sequence (concat (yaml-indent (pop s)) "-\\n")
            case _ (concat (yaml-indent (pop s)) "- ")
        case _ (fail :protocol-order "the events hold a value where a key is due, which a tree's never do")

; A held sequence is opened by its first item.
def yaml-opened [s]
  match (count s)
    case 0 s
    case _
      match (yaml-top s)
        case :array-open (yaml-mark :array s)
        case _ s

def yaml-opening [s]
  match (count s)
    case 0 ""
    case _
      match (yaml-top s)
        case :array-open (yaml-lead :sequence (pop s))
        case _ ""

def yaml-number [n]
  match (number-class n)
    case :finite (scalar-text csv-options n)
    case :infinity ".inf"
    case :negative-infinity "-.inf"
    case :nan ".nan"

; A string in the double-quoted form: \`quoted\`'s, with the line
; separators U+2028 and U+2029, which YAML 1.2 reads as themselves and
; YAML 1.1 as line breaks, written as their escapes too.
def yaml-quoted [text]
  replace-text "\\u2029" "\\\\u2029"
    replace-text "\\u2028" "\\\\u2028"
      quoted text

def yaml-scalar [value]
  match (kind value)
    case :null "null"
    case :boolean
      match value
        case true "true"
        case false "false"
    case :number (yaml-number value)
    case _ (yaml-quoted value)

; A key at the column \`at\`: implicit while its written form is at most
; 1024 characters, past which YAML stops reading an implicit key, and
; explicit beyond, \`? key\` on its own line and the value after a \`:\` at
; the key's column.
def yaml-key [name at]
  match (yaml-implicit-key name)
    case true (concat (yaml-quoted name) ":")
    case false (concat "? " (yaml-quoted name) "\\n" at ":")

; Whether a key's written form is at most 1024 characters. It is the
; quoted form, unless the key holds a line separator, whose escape adds
; five characters \`length\` cannot count; then a key of at most 170
; characters is short enough, since no character is written as more
; than six.
def yaml-implicit-key [name]
  match (compare (length (quoted name)) 1024)
    case :greater false
    case _
      match (chars-within yaml-separator-free name)
        case true true
        case false
          match (compare (length name) 170)
            case :greater false
            case _ true

; Every character but the line separators U+2028 and U+2029.
def yaml-separator-free [[0 8231] [8234 1114111]]

; A key, written where the mapping's keys go.
def yaml-member [name s]
  match (yaml-top s)
    case :object-open
      transition (yaml-mark :member s) [(yaml-lead :mapping (pop s)) (yaml-key name (yaml-indent (pop s)))]
    case :object
      transition (yaml-mark :member s) [(yaml-indent (pop s)) (yaml-key name (yaml-indent (pop s)))]
    case _ (fail :protocol-order "the events hold a key where a value is due, which a tree's never do")

; The state a value may begin in: anywhere but a mapping waiting for a key.
def yaml-value [s]
  match (yaml-top s)
    case :object-open (fail :protocol-order "the events hold a value where a key is due, which a tree's never do")
    case :object (fail :protocol-order "the events hold a value where a key is due, which a tree's never do")
    case _ s

; The outputs of a step whose next state is s, with the end of a record
; after them when s is one level deep: the root opened, or a value
; directly inside it ended (or the root itself, where the mark is the
; document's end).
def yaml-ended [s outputs]
  match (count s)
    case 1 (push :record-end outputs)
    case _ outputs

def yaml-step [s event]
  match (yaml-top s)
    case :root-done (fail :protocol-order "the events hold more after the root value, which a tree's never do")
    case _ (yaml-event s event)

def yaml-event [s event]
  match event
    case object-start
      let [s2 (push :object-open (yaml-opened (yaml-value s)))]
        transition s2 (yaml-ended s2 [(yaml-opening s)])
    case array-start
      let [s2 (push :array-open (yaml-opened (yaml-value s)))]
        transition s2 (yaml-ended s2 [(yaml-opening s)])
    case (key name) (yaml-member name s)
    case (scalar value)
      let [s2 (yaml-opened (yaml-value s))]
        let [s3 (yaml-done s2)]
          transition s3 (yaml-ended s3 [(yaml-opening s) (yaml-lead :scalar s2) (yaml-scalar value) "\\n"])
    case object-end
      match (yaml-top s)
        case :object-open
          let [s2 (yaml-done (pop s))]
            transition s2 (yaml-ended s2 [(yaml-lead :scalar (pop s)) "{}\\n"])
        case :object
          let [s2 (yaml-done (pop s))]
            transition s2 (yaml-ended s2 [])
        case :member
          fail :protocol-order "the events end a mapping after a key and before its value, which a tree's never do"
        case _
          fail :protocol-order "the events end a mapping that is not open, which a tree's never do"
    case array-end
      match (yaml-top s)
        case :array-open
          let [s2 (yaml-done (pop s))]
            transition s2 (yaml-ended s2 [(yaml-lead :scalar (pop s)) "[]\\n"])
        case :array
          let [s2 (yaml-done (pop s))]
            transition s2 (yaml-ended s2 [])
        case _
          fail :protocol-order "the events end a sequence that is not open, which a tree's never do"

def yaml-finish [s]
  match (yaml-top s)
    case :root-done []
    case :none (fail :protocol-order "the events hold no value, where a tree's hold one")
    case _ (fail :protocol-order "the events ended inside a container")

; The render: the tree's events in, the document's text out.
def yaml-render [input]
  join ""
    scan-emit [] yaml-step yaml-finish (events input)
` }),
  transduce: Object.freeze({ entry: "yaml-transduce", source: `; YAML's transducer part: the document's JSON events from the yaml
; grammar's rule passes, for a host that reads parser events (alchemy-cli's
; \`translate\` and \`run --grammar yaml\`). It is hand-written, since the
; grammar builds its block structure and the relaxed forms it shares with
; jsonic in its actions, which the passes do not show, and every event is
; the one the walk of the grammar's value under its default options gives:
; the options every host that reads a part builds the grammar with, which
; the passes do not carry.
;
; The passes: a \`map\`'s open and close an object, a flow \`list\`'s an
; array, and the \`val\` or \`indent\` whose open pushes \`yamlBlockList\`, the
; block sequence, an array that its own close ends; \`yamlBlockList\` and
; \`yamlBlockElem\`, the items, pass by. A sequence's mapping, \`yamlElemMap\`
; (\`- a: 1\`), opens an object and is replaced by its pairs in the same
; frame, so the close of its last pair, the one whose alternate replaces
; it with nothing, ends the object. A \`pair\` opened on its key alternate,
; and a \`yamlElemPair\`, announces its key from its key token (a string's
; value, any other token's source; the token after \`?\` on an explicit
; key), held until the value begins; a pair opened on a separator with no
; key announces nothing. A \`val\` yields its scalar at its close, from the
; value the close carries, so that adjacent scalars (\`"a" "b"\`), an
; implicit list the close replaces the val with \`list\` for, start the
; array before the first and the list's open starts no second one. An
; undefined value (\`a:\`, \`- \`, an alias nothing defines) is null in a
; mapping, at the root and as a block sequence's item, nothing in a flow
; sequence, and nothing, its key dropped, in a sequence's mapping, as the
; grammar keeps each; an \`elem\` opened on a separator with no value
; (\`[a, , b]\`) is a null element; a stream of directives and document
; markers alone (\`...\`) makes a \`stream\` pass and no value, null at
; \`finish\`, as the empty document is.
;
; What the passes cannot show the part refuses in its own words
; (\`fail :unstreamable\`, STREAMABILITY_UNKNOWN), and a host that reads a
; part reads such a document whole: an alias to a mapping or a sequence,
; whose resolved value the token carries whole and no part can expand into
; events, and a plain \`<<\` merge key, whose members the grammar folds into
; the mapping after the passes (a quoted \`"<<"\` is a member). A stream of
; several documents streams its first before the sequence of them is
; known, a second root to the tree contract a host puts after the part,
; read whole the same way. Over the 566 inputs of \`test/spec/*.tsv\`, the
; part writes what the walk writes for 533 and refuses the other 33 so.
;
; The state is [stack carry rooted pending]: a marker per open rule whose
; close will come, innermost last (:object for a map, :array for a flow
; list, :block-array for the val or indent whose open pushed the block
; list, :elem-object for a yamlElemMap, :leaf for a val that pushed
; nothing, :undefined for one whose token is an unresolved alias, :skip
; for any other rule); whether a val's close made an implicit list, so the
; list's open starts no array; whether a value has begun; and the key a
; pair announced whose value has not begun, or missing. Nothing grows with
; the document's length, only with its nesting, under max_metadata_bytes.

def yaml-transduce-has-key [groups]
  match (count (filter (fn [g] (match g (case "key" true) (case _ false))) groups))
    case 0 false
    case _ true

def yaml-transduce-has-null [groups]
  match (count (filter (fn [g] (match g (case "null" true) (case _ false))) groups))
    case 0 false
    case _ true

def yaml-transduce-key-text [token]
  match (kind (get :val token))
    case :string (get :val token)
    case _ (get :src token)

; The key a pair announces: a plain \`<<\` is a merge key, whose members
; the grammar folds into the mapping after the passes, which no part can
; follow.
def yaml-transduce-key [token]
  match (get :name token)
    case "#TX"
      match (get :val token)
        case "<<" (fail :unstreamable "a merge key, whose members the grammar folds into the mapping after the passes")
        case _ (yaml-transduce-key-text token)
    case _ (yaml-transduce-key-text token)

; The token a pair's open announces its key with: the first on the key
; alternate, the one after \`?\` on an explicit key's (\`{? a : 1}\`), none
; on any other (a separator with no key).
def yaml-transduce-key-token [rule]
  match (yaml-transduce-has-key (yaml-transduce-groups rule))
    case true (transduce-token 0 rule)
    case _
      match (transduce-token 0 rule)
        case missing missing
        case token
          match (get :name token)
            case "#QM" (transduce-token 1 rule)
            case _ missing

; The token a sequence's pair (yamlElemPair) announces its key with: its
; first, or the one after \`?\` on an explicit key's.
def yaml-transduce-elem-key-token [rule]
  match (transduce-token 0 rule)
    case missing missing
    case token
      match (get :name token)
        case "#QM" (transduce-token 1 rule)
        case _ token

def yaml-transduce-groups [rule]
  match (get :alt rule)
    case missing []
    case alt (get :g alt)

def yaml-transduce-pushes [rule]
  match (get :alt rule)
    case missing ""
    case alt (get :p alt)

def yaml-transduce-replaces [rule]
  match (get :alt rule)
    case missing ""
    case alt (get :r alt)

; The innermost container the stack holds, or missing at the root.
def yaml-transduce-container [stack]
  let [containers (filter (fn [m] (match m (case :object true) (case :array true) (case :block-array true) (case :elem-object true) (case _ false))) stack)]
    match (count containers)
      case 0 missing
      case _ (top containers)

; A value's first events, after the key pending for it, if one is.
def yaml-transduce-value [pending events]
  match pending
    case missing events
    case name
      match (count events)
        case 1 [(key name) (get-path (path 0) events)]
        case _ [(key name) (get-path (path 0) events) (get-path (path 1) events)]

; A val that pushed nothing: a leaf, unless its token is an alias, which
; the grammar resolved to the aliased value; one to a mapping or a
; sequence holds members the passes do not show, and one to nothing is
; undefined.
def yaml-transduce-leaf-open [stack carry pending rule]
  match (transduce-token 0 rule)
    case missing (transition [(push :leaf stack) carry true pending] [])
    case token
      match (kind (get :val token))
        case :record
          match (get "__yamlAlias" (get :val token))
            case missing (fail :unstreamable "an alias to a mapping, whose members the passes do not show")
            case _ (transition [(push :undefined stack) carry true pending] [])
        case :vector (fail :unstreamable "an alias to a sequence, whose elements the passes do not show")
        case _ (transition [(push :leaf stack) carry true pending] [])

def yaml-transduce-val-open [stack carry pending rule]
  match (yaml-transduce-pushes rule)
    case "yamlBlockList" (transition [(push :block-array stack) carry true missing] (yaml-transduce-value pending [array-start]))
    case "" (yaml-transduce-leaf-open stack carry pending rule)
    case _ (transition [(push :skip stack) carry true pending] [])

def yaml-transduce-open [stack carry rooted pending rule]
  match (get :name rule)
    case "map" (transition [(push :object stack) carry true missing] (yaml-transduce-value pending [object-start]))
    case "list"
      match carry
        case true (transition [(push :array stack) false true pending] [])
        case _ (transition [(push :array stack) carry true missing] (yaml-transduce-value pending [array-start]))
    case "val" (yaml-transduce-val-open stack carry pending rule)
    case "indent"
      match (yaml-transduce-pushes rule)
        case "yamlBlockList" (transition [(push :block-array stack) carry true missing] (yaml-transduce-value pending [array-start]))
        case _ (transition [(push :skip stack) carry rooted pending] [])
    case "pair"
      match (yaml-transduce-key-token rule)
        case missing (transition [(push :skip stack) carry rooted pending] [])
        case token (transition [(push :skip stack) carry rooted (yaml-transduce-key token)] [])
    case "elem"
      match (yaml-transduce-has-null (yaml-transduce-groups rule))
        case true (transition [(push :skip stack) carry true pending] [(scalar null)])
        case _ (transition [(push :skip stack) carry rooted pending] [])
    case "yamlElemMap"
      match (yaml-transduce-replaces rule)
        case "yamlElemPair" (transition [(push :elem-object stack) carry true missing] (yaml-transduce-value pending [object-start]))
        case _ (transition [(push :object stack) carry true missing] (yaml-transduce-value pending [object-start]))
    case "yamlElemPair"
      match (yaml-transduce-elem-key-token rule)
        case missing (transition [(push :skip stack) carry rooted pending] [])
        case token (transition [(push :skip stack) carry rooted (yaml-transduce-key token)] [])
    case "stream"
      match (yaml-transduce-replaces rule)
        case "stream" (transition [stack carry rooted pending] [])
        case _ (transition [(push :skip stack) carry rooted pending] [])
    case _ (transition [(push :skip stack) carry rooted pending] [])

; An undefined value: null in a mapping, at the root and as a block
; sequence's item; nothing in a flow sequence; and nothing, its key
; dropped, in a sequence's mapping, as the grammar keeps each.
def yaml-transduce-undefined [rest carry pending]
  match (yaml-transduce-container rest)
    case :array (transition [rest carry true missing] [])
    case :elem-object (transition [rest carry true missing] [])
    case _ (transition [rest carry true missing] (yaml-transduce-value pending [(scalar null)]))

; A leaf's close: its value, from the value the close carries; a close
; whose alternate replaces the val with list is the first element of an
; implicit list, which starts before it.
def yaml-transduce-leaf [rest carry pending rule]
  match (get :value rule)
    case missing (yaml-transduce-undefined rest carry pending)
    case value
      match (yaml-transduce-replaces rule)
        case "list" (transition [rest true true missing] (yaml-transduce-value pending [array-start (scalar value)]))
        case _ (transition [rest carry true missing] (yaml-transduce-value pending [(scalar value)]))

def yaml-transduce-close [stack carry rooted pending rule]
  let [rest (pop stack)]
    match (top stack)
      case :leaf (yaml-transduce-leaf rest carry pending rule)
      case :undefined (yaml-transduce-undefined rest carry pending)
      case :object (transition [rest carry rooted pending] [object-end])
      case :array (transition [rest carry rooted pending] [array-end])
      case :block-array (transition [rest carry rooted pending] [array-end])
      case :elem-object (transition [rest carry rooted pending] [object-end])
      case _
        match (get :name rule)
          case "yamlElemPair"
            match (yaml-transduce-replaces rule)
              case "yamlElemPair" (transition [rest carry rooted pending] [])
              case _
                match (top rest)
                  case :elem-object (transition [(pop rest) carry rooted pending] [object-end])
                  case _ (transition [rest carry rooted pending] [])
          case _ (transition [rest carry rooted pending] [])

def yaml-transduce-step [state pass]
  match state
    case [stack carry rooted pending]
      match pass
        case (open rule) (yaml-transduce-open stack carry rooted pending rule)
        case (close rule) (yaml-transduce-close stack carry rooted pending rule)

def yaml-transduce-finish [state]
  match state
    case [[] carry false pending] [(scalar null)]
    case [[] carry true pending] []
    case _ (fail :protocol-order "the rule passes ended inside a container, which a tree's never do")

def yaml-transduce [input]
  as-events (scan-emit [[] false false missing] yaml-transduce-step yaml-transduce-finish (parser-events input))
` })
})

function translate (): TranslationParts | undefined {
  return TRANSLATION
}

export {
  translate,
}

export type {
  TranslationPart,
  TranslationParts,
}
